func:
// Determine curfew state from the schedule itself (lock_time/unlock_time),
// not from status.locking.mode. On real hardware, mode has been observed to
// just hold whatever explicit value (0-3) was last set rather than ever
// reporting the documented -1 (curfew engaged) / -2 (curfew released)
// states - so a mode-based trigger can silently never fire, leaving the
// flap permanently unlocked despite curfew being enabled.
//
// lock_time/unlock_time are in UTC (confirmed live: comparing them against
// local getHours()/getMinutes() on a device whose system clock is local,
// e.g. CEST, releases the lock hours before the real scheduled time) - so
// compare against the UTC clock fields, not local ones.

// 'Device Status' emits one message per device in the household, including
// non-flap devices like the Hub. Those have no control.curfew at all, so
// msg.payload.curfew is undefined here - skip them rather than treating
// 'no curfew field' the same as 'curfew not currently active', which would
// re-issue an unlock to a device that was never locked in the first place.
if (!msg.payload.curfew) {
    return null;
}

function toMinutes(hhmm) {
    const [h, m] = hhmm.split(':').map(Number);
    return h * 60 + m;
}

const curfews = msg.payload.curfew || [];
const deviceId = msg.payload.deviceId;
const now = new Date();
const nowMinutes = now.getUTCHours() * 60 + now.getUTCMinutes();

const curfewActive = curfews.some(c => {
    if (!c.enabled) return false;
    const lockMinutes = toMinutes(c.lock_time);
    const unlockMinutes = toMinutes(c.unlock_time);
    // Overnight windows (e.g. 20:00-07:00) wrap past midnight.
    return lockMinutes <= unlockMinutes
        ? nowMinutes >= lockMinutes && nowMinutes < unlockMinutes
        : nowMinutes >= lockMinutes || nowMinutes < unlockMinutes;
});

if (curfewActive) {
    // Only lock both ways once every chip has been seen inside - otherwise
    // a straggler gets locked out entirely. Unknown status (no pet poll
    // yet) counts as "someone might still be out".
    if (flow.get('anyPetOutside') !== false) {
        node.status({ fill: 'yellow', shape: 'ring', text: 'curfew window - holding, pet(s) outside or unconfirmed' });
        return null;
    }
    node.status({ fill: 'red', shape: 'dot', text: 'curfew window - locking both ways' });
    msg.payload = { deviceId, lockState: 3 };
    return msg;
}

// Outside the curfew window - make sure it's unlocked
node.status({ fill: 'green', shape: 'dot', text: 'no curfew - unlocked' });
msg.payload = { deviceId, lockState: 0 };
return msg;

// Keep a running per-pet inside/outside map in flow context, keyed by
// chip/pet id, and derive a single anyPetOutside flag from it. Starts
// unknown (undefined) until every pet has been seen at least once.
const pets = flow.get('petLocations') || {};
pets[msg.payload.id] = msg.payload.where; // 1 = inside, 2 = outside
flow.set('petLocations', pets);

const anyPetOutside = Object.values(pets).some(where => where === 2);
flow.set('anyPetOutside', anyPetOutside);

const outsideCount = Object.values(pets).filter(where => where === 2).length;
node.status({
    fill: anyPetOutside ? 'yellow' : 'green',
    shape: 'dot',
    text: `${Object.keys(pets).length} pet(s) tracked, ${outsideCount} outside`
});

return null;
